 if(legendary)return pool.map(s=>({id:s.id,tier:s.rarityTier,probability:1/pool.length}));
 const tiers=[...new Set(pool.map(s=>s.rarityTier))];const tierTotal=tiers.reduce((n,t)=>n+(VK_TIER_WEIGHT[t]||0),0);
 const base=pool.map(s=>{const peers=pool.filter(p=>p.rarityTier===s.rarityTier);const score=p=>p.habitats[0]===region?1.4:1;return{id:s.id,tier:s.rarityTier,probability:(VK_TIER_WEIGHT[s.rarityTier]/tierTotal)*score(s)/peers.reduce((n,p)=>n+score(p),0)}});
