function updateWorldCamera(){
 const canvas=document.getElementById('map');
 const frame=canvas&&canvas.parentElement;
 if(!canvas||!frame||!window.matchMedia('(max-width:760px) and (orientation:portrait)').matches){if(canvas)canvas.style.left='';return;}
 const frameW=frame.clientWidth,frameH=frame.clientHeight;
 if(!frameW||!frameH)return;
 const scaledW=W*T*frameH/(H*T);
 const pos=(typeof walkX==='number'&&walkX!==null?walkX:data.x);
 const playerX=(pos+0.5)*T*frameH/(H*T);
 const minLeft=Math.min(0,frameW-scaledW);
 const left=Math.max(minLeft,Math.min(0,frameW/2-playerX));
 canvas.style.left=left+'px';
}
