 ctx.fillStyle='#254d3b66';ctx.beginPath();ctx.ellipse(px+12,py+20,12,4,0,0,7);ctx.fill();
 ctx.fillStyle='#735038';ctx.fillRect(px+10,py+12,5,10);
 const foliage=pink?['#c9619b','#f1a1c5','#ffd3e6']:autumn?['#8e7136','#d6a94e','#f5d888']:['#1c6e43','#32985b','#7bc766'];
 for(const [ox,oy,r,c] of [[4,10,8,0],[18,10,8,0],[11,5,10,1],[12,1,6,2]]){ctx.fillStyle=foliage[c];ctx.beginPath();ctx.arc(px+ox,py+oy,r,0,7);ctx.fill()}
