let vkWallCache=null;
function vkDrawCachedWorldWalls(){
 if(!vkWallCache||vkWallCache.width!==W*T||vkWallCache.height!==H*T){
  vkWallCache=document.createElement('canvas');
  vkWallCache.width=W*T;vkWallCache.height=H*T;
  const wallContext=vkWallCache.getContext('2d');
  vkPaintWorldWalls(wallContext);
 }
 ctx.drawImage(vkWallCache,0,0);
}
function vkPaintWorldWalls(ctx){
// Solid pixel-art boundary walls replace the flat green edge bands.
// Drawn on the map itself so no blurry overlays or aspect-ratio changes occur.
ctx.save();
for(const side of [0,W*T-24]){
  ctx.fillStyle='#344a56';ctx.fillRect(side,0,24,H*T);
  ctx.fillStyle='#71838a';ctx.fillRect(side+(side===0?19:0),0,5,H*T);
  ctx.fillStyle='#243944';ctx.fillRect(side+(side===0?0:21),0,3,H*T);
  for(let yy=0;yy<H*T;yy+=24){
    ctx.fillStyle=(Math.floor(yy/24)%2===0)?'#526774':'#475d6a';
    ctx.fillRect(side+3,yy+2,17,19);
    ctx.fillStyle='#82939b';ctx.fillRect(side+3,yy+2,17,2);
    ctx.fillStyle='#2c414d';ctx.fillRect(side+3,yy+20,17,2);
    ctx.fillStyle='#9aa7a8';ctx.fillRect(side+11,yy+3,2,7);
  }
}
ctx.restore();
}
