 $('battleactions').innerHTML=options.map(([id,name])=>`<button data-action="${id}" ${((id==='catch'&&!data.spheres)||(id==='premium'&&!data.premium)||(id==='potion'&&!data.potions)||(id==='mega'&&!data.megaPotions)||(id==='teamheal'&&!data.teamPotions)||((battle.trainer||battle.legend)&&['catch','premium','flee'].includes(id))||(id.startsWith('swap:')&&(data.team[+id.split(':')[1]].hp<=0||data.team[+id.split(':')[1]].uid===m.uid)))?'disabled':''}>${name}</button>`).join('');
