const strengths={"Feuer":["Natur","Eis"],"Natur":["Wasser","Erde"],"Wasser":["Feuer","Stein"],"Blitz":["Wasser","Luft"],"Erde":["Blitz","Stahl"],"Luft":["Natur","Gift"],"Eis":["Luft","Drache"],"Dunkel":["Licht","Psycho"],"Licht":["Dunkel","Geist"],"Geist":["Psycho","Erde"],"Stein":["Feuer","Blitz"],"Stahl":["Stein","Eis"],"Drache":["Stahl","Licht"],"Gift":["Geist","Drache"],"Psycho":["Dunkel","Gift"]};
const immunities={};
function typeMultiplier(attackType,defenseType){if(attackType==='Normal')return 1;if((immunities[attackType]||[]).includes(defenseType))return .5;if((strengths[attackType]||[]).includes(defenseType))return 1.35;if((strengths[defenseType]||[]).includes(attackType))return .75;return 1}
function attack(a,b,strong,moveType='element'){let sa=MS(a),sb=MS(b),element=strong?sa.type:'Normal',bonus=typeMultiplier(element,sb.type)*(strong&&element===weatherType()?weather()[1]:1);if(a.status==='sleep'&&Math.random()<.5){a.status=null;return displayName(a)+' erwacht!'}if(a.status==='stun'&&Math.random()<.25)return displayName(a)+' ist paralysiert!';let raw=(sa.atk+a.lv*.85)*statBoost(a)*(strong?1.35:1)*bonus-(sb.def+b.lv*.25)*statBoost(b)*.45;let d=Math.max(2,Math.floor(raw*(.85+Math.random()*.3)));if(moveType==='heavy')d=Math.floor(d*1.4);if(moveType==='guard'){a.shield=2;d=Math.floor(d*.55)}if(b.shield>0){d=Math.ceil(d*.6);b.shield--}b.hp=Math.max(0,b.hp-d);if(moveType==='drain')a.hp=Math.min(maxhp(a),a.hp+Math.ceil(d*.35));if(moveType==='status'&&Math.random()<.5)b.status=['burn','poison','stun','sleep'][SPECIES.findIndex(x=>x.id===a.id)%4];return `${sa.name} nutzt ${strong?element+'-Attacke':'Normalangriff'} und verursacht ${d} Schaden${bonus>1?' – sehr effektiv!':bonus<1?' – wenig effektiv!':''}${b.status?' · '+b.status+'!':''}.`}
function gain(m,xp){m.xp+=xp;let notes=[];while(m.xp>=m.lv*20){m.xp-=m.lv*20;m.lv++;m.hp=maxhp(m);notes.push(`${S(m.id).name} erreicht Level ${m.lv}!`);let s=MS(m);if(s.evo&&m.lv>=s.at){m.id=s.evo;data.seen=[...new Set([...data.seen,m.id])];m.hp=maxhp(m);notes.push(`✨ Entwicklung zu ${S(m.id).name}!`)}}return notes.join(' ')}
function finish(msg,win){battleMenu='main';let m=active(),wasTrainer=battle.trainer;if(win&&wasTrainer&&battle.index<3){let defeated=battle.enemy;let xp=20+defeated.lv*6;msg+=' '+gain(m,xp);battle.index++;battle.enemy=battle.team[battle.index];data.seen=[...new Set([...data.seen,battle.enemy.id])];battle.log=msg+' Trainer schickt '+S(battle.enemy.id).name+'!';battle.turn++;save();renderBattle();return}if(win){if(battle.legend){data.legendWins++;data.legendCleared[data.zone]=true;let prize=monster(battle.enemy.id,Math.max(1,levelBase()),false);prize.evolved=true;prize.evoTitle='Abyss Sovereign';prize.hp=maxhp(prize);data.storage.push(prize);msg+=' 🐉 Legendäres Monster als Belohnung im Lager!'}if(wasTrainer){data.trainerWins++;if(battle.boss)data.bossWins++}else data.wildWins++;let gold=Math.floor((22+battle.enemy.lv*5+(wasTrainer?180+data.zone*18+(battle.boss?900+data.zone*30:0):0))*(1+data.buildings.treasury*.1)),xp=Math.floor((18+battle.enemy.lv*9)*(1+data.buildings.training*.1));data.coins+=gold;msg+=` +${gold} Münzen. `+gain(m,xp);if(wasTrainer){data.trainerCleared=true;data.clearedZones=data.clearedZones||{};data.clearedZones[data.zone]=true;msg+=(battle.boss?' 👑 BIOM-BOSS besiegt! Extragold erhalten. Das nächste Biom ist freigeschaltet!':'')+' 🏅 Tippe auf die Medaille in der Arena, um weiterzureisen!'}}battle=null;$('battleoverlay').classList.add('hidden');save();if(msg)gameNotice(msg)}
function enemyMove(msg){let e=battle.enemy,m=active();if(e.status==='burn'||e.status==='poison'){let damage=Math.max(1,Math.floor(maxhp(e)*.04));e.hp=Math.max(0,e.hp-damage);msg+=' '+displayName(e)+' erleidet '+damage+' Statusschaden.'}if(m.status==='burn'||m.status==='poison'){let damage=Math.max(1,Math.floor(maxhp(m)*.04));m.hp=Math.max(0,m.hp-damage);msg+=' '+displayName(m)+' erleidet '+damage+' Statusschaden.'}if(e.hp<=0){finish(msg+' Sieg!',true);return}let enemyType=MS(e).type,playerType=MS(m).type;
let elemAdvantage=typeMultiplier(enemyType,playerType);
let elementalChance=(battle.boss?.76:battle.trainer?.57:.38)+(elemAdvantage>1?.16:elemAdvantage<1?-.12:0);
let useElement=Math.random()<Math.min(.93,Math.max(.15,elementalChance));
msg+=' '+attack(e,m,useElement);if(m.hp<=0){let replacement=data.team.find(a=>a.hp>0);if(replacement){data.active=replacement.uid;msg+=` ${S(m.id).name} ist kampfunfähig! ${S(replacement.id).name} übernimmt.`}else{data.team.forEach(x=>{x.hp=maxhp(x);x.status=null;x.shield=0});data.x=12;data.y=28;data.active=data.team[0].uid;const penalty=Math.min(data.coins,Math.ceil(data.coins*.10));data.coins-=penalty;finish('💧 Dein Team wurde vollständig geheilt. Du bist am Heilbrunnen und verlierst '+penalty+' Münzen (10 %).',false);vkStartRespawnCountdown();return}}battle.turn++;battle.log=msg;save();renderBattle()}
function action(id){if(!battle)return;if(id.startsWith('menu:')){battleMenu=id.slice(5);renderBattle();return}battleMenu='main';let m=active(),e=battle.enemy;if(id.startsWith('swap:')){let i=+id.split(':')[1];if(data.team[i]&&data.team[i].hp>0&&data.team[i].uid!==m.uid){data.active=data.team[i].uid;enemyMove('🔁 '+S(data.team[i].id).name+' wurde eingewechselt!')}return}if(id==='flee'){if(battle.trainer||battle.legend)return;if(Math.random()<.85){finish('Du bist entkommen.',false);return}enemyMove('Flucht misslungen!');return}
if(id==='mega'){if(!data.megaPotions)return;data.megaPotions--;m.hp=maxhp(m);enemyMove('❤️ Mega-Heiltrank heilt '+displayName(m)+' vollständig.');return}
if(id==='teamheal'){if(!data.teamPotions)return;data.teamPotions--;data.team.forEach(x=>x.hp=maxhp(x));enemyMove('💚 Das ganze Team wurde geheilt.');return}
if(id==='potion'){if(!data.potions)return;data.potions--;m.hp=Math.min(maxhp(m),m.hp+25);enemyMove('Dein Monster wird um bis zu 25 LP geheilt.');return}
if(id==='catch'||id==='premium'){if(battle.trainer||battle.legend)return;if(id==='catch'&&!data.spheres||id==='premium'&&!data.premium)return;if(id==='catch')data.spheres--;else data.premium--;let chance=Math.min(.93,(id==='premium'?.43:.22)+(.68*(1-e.hp/maxhp(e)))+Math.max(0,(m.lv-e.lv)*.012));if(Math.random()<chance){let dest=data.team.length<4?'team':'storage';data[dest].push(e);data.catches++;finish(`${S(e.id).name} gefangen! ${dest==='team'?'Im Team':'Ins Lager geschickt'}.`,false);return}enemyMove('Die Sphäre wackelt … aber das Monster bricht aus!');return}
if(['attack','skill','heavy','guard','drain','status'].includes(id)){let msg=attack(m,e,id!=='attack',id==='skill'?'element':id);if(e.hp<=0){finish(msg+' Gegnerisches Monster besiegt!',true);return}enemyMove(msg)}}
document.addEventListener('click',ev=>{let b=ev.target.closest('[data-tab],[data-move],[data-starter],[data-action],[data-buy],[data-active],[data-store],[data-withdraw],[data-sell],[data-travel],[data-nextzone],[data-breed],[data-evolve],[data-teleport],[data-usexp],[data-build],[data-claim],[data-legend]');if(!b)return;if((b.dataset.active||b.dataset.store||b.dataset.withdraw)&&!(b.dataset.active?window.VaelkorTeamAccess?.canActivate(b.dataset.active):window.VaelkorTeamAccess?.canEdit())){gameNotice('Ein- und Auslagern nur in der Zuchtanlage. Das aktive Teammonster kannst du unterwegs wechseln.');return;}if(b.hasAttribute('data-legend')){startLegend();return}else if(b.dataset.build){if(b.dataset.build==='nursery')return;let id=b.dataset.build,n=data.buildings[id],cost=400*(n+1);if(n<5&&data.coins>=cost){data.coins-=cost;data.buildings[id]++;save()}return}else if(b.dataset.claim){let q=QUESTS.find(q=>q[0]===b.dataset.claim);if(q&&!data.questsClaimed[q[0]]&&q[2](data)){data.questsClaimed[q[0]]=true;data.coins+=q[3];save()}return}else if(b.dataset.usexp){let [uid,size]=b.dataset.usexp.split(':');useExp(uid,size);return}else if(b.hasAttribute('data-breed')){breed();return}else if(b.hasAttribute('data-teleport')){teleport();return}else if(b.dataset.evolve){evolveMonster(b.dataset.evolve);return}else if(b.hasAttribute('data-nextzone')){nextZone();return}else if(b.dataset.travel){travelBack(Number(b.dataset.travel));return}else if(b.dataset.tab){stopHeldMovement();document.querySelectorAll('[data-tab]').forEach(n=>n.classList.toggle('active',n===b));['world','team','shop','breeding','guide','base','quests'].forEach(t=>$(t).classList.toggle('hidden',t!==b.dataset.tab));render()}else if(b.dataset.move){if(b.dataset.move==='center'&&!document.getElementById('vkIntegratedWorld'))move(0,0);return}else if(b.dataset.starter)chooseStarter(b.dataset.starter);else if(b.dataset.action)action(b.dataset.action);else if(b.dataset.buy){let id=b.dataset.buy,cost=id.startsWith('stone:')?750:{sphere:75,megasphere:240,hypersphere:600,potion:45,super:110,mega:270,teamheal:580,teleport:350,'exp:small':120,'exp:medium':360,'exp:large':1050}[id];if(data.coins>=cost){data.coins-=cost;if(id.startsWith('stone:')){let type=id.slice(6);data.stones[type]=(data.stones[type]||0)+1}else if(id.startsWith('exp:')){data.expPotions[id.slice(4)]++}else{let key={sphere:'spheres',megasphere:'megaSpheres',hypersphere:'hyperSpheres',potion:'potions',super:'premium',mega:'megaPotions',teamheal:'teamPotions',teleport:'teleporters'}[id];data[key]=(data[key]||0)+1;}save()}}else if(b.dataset.active){data.active=data.team.find(m=>String(m.uid)===b.dataset.active)?.uid||data.active;save()}else if(b.dataset.store){let i=data.team.findIndex(m=>String(m.uid)===b.dataset.store);if(i>=0&&data.team.length>1){data.storage.push(data.team.splice(i,1)[0]);ensureActive();save()}}else if(b.dataset.sell){let i=data.storage.findIndex(m=>String(m.uid)===b.dataset.sell);if(i>=0){let m=data.storage[i],price=sellPrice(m);if(confirm(S(m.id).name+" für "+price+" Münzen verkaufen? Das Monster wird dauerhaft entfernt.")){data.storage.splice(i,1);data.coins+=price;save()}}}else if(b.dataset.withdraw){let i=data.storage.findIndex(m=>String(m.uid)===b.dataset.withdraw);if(i>=0&&data.team.length<4){data.team.push(data.storage.splice(i,1)[0]);save()}}});
