// Pfeiltasten/WASD und Touch-D-Pad lassen sich gedrueckt halten.
const directionKeys={ArrowUp:[0,-1],KeyW:[0,-1],ArrowDown:[0,1],KeyS:[0,1],ArrowLeft:[-1,0],KeyA:[-1,0],ArrowRight:[1,0],KeyD:[1,0]};
const directionButtons={up:[0,-1],down:[0,1],left:[-1,0],right:[1,0]};
let heldDirection=null,heldTimer=null,heldButton=null;
function stopHeldMovement(){if(heldTimer!==null){clearInterval(heldTimer);heldTimer=null}heldDirection=null;heldButton=null}
function tryHeldStep(){
 if(document.getElementById('vkIntegratedWorld')){stopHeldMovement();return;}
 if(!heldDirection||battle||!$('starteroverlay').classList.contains('hidden')){stopHeldMovement();return}
 if($('world').classList.contains('hidden')){stopHeldMovement();return}
 if(!walking)move(...heldDirection);
}
function startHeldMovement(direction,button=null){
 stopHeldMovement();heldDirection=direction;heldButton=button;
 tryHeldStep();heldTimer=setInterval(tryHeldStep,145);
}
window.addEventListener('keydown',e=>{
 if(document.getElementById('vkIntegratedWorld'))return;
 const dir=directionKeys[e.code];if(!dir||/^(INPUT|TEXTAREA|SELECT)$/.test(document.activeElement?.tagName||''))return;
 if(battle||!$('starteroverlay').classList.contains('hidden'))return;
 e.preventDefault();
 if(heldDirection&&heldButton===e.code)return;
 startHeldMovement(dir,e.code);
});
window.addEventListener('keyup',e=>{if(heldButton===e.code)stopHeldMovement()});
window.addEventListener('blur',stopHeldMovement);document.addEventListener('visibilitychange',()=>{if(document.hidden)stopHeldMovement()});
document.addEventListener('visibilitychange',()=>{if(document.hidden)stopHeldMovement()});
document.querySelectorAll('.dpad [data-move]').forEach(button=>{
 const dir=directionButtons[button.dataset.move];if(!dir)return;
 button.style.touchAction='none';
 button.addEventListener('pointerdown',e=>{
  if(e.button!==0)return;
  e.preventDefault();button.setPointerCapture?.(e.pointerId);
  startHeldMovement(dir,'pointer:'+e.pointerId);
 });
 button.addEventListener('pointerup',stopHeldMovement);
 button.addEventListener('pointercancel',stopHeldMovement);
 button.addEventListener('lostpointercapture',stopHeldMovement);
});
