const DD=window.AetherEngine;
const FKEY='monora-dueldeck-fusion-v5'; // Save-Kompatibilität mit v1.0
let fusion=vkUnifiedLoaded?vkUnifiedLoaded.fusion:null;
if(!fusion){try{fusion=JSON.parse(localStorage.getItem(FKEY))}catch(e){console.warn('VAELKOR: alter Karten-Spielstand nicht lesbar',e)}}
if(!fusion||typeof fusion!=='object'||!Array.isArray(fusion.deck))fusion={deck:[],owned:{},coins:0,wins:0,losses:0};
if(!fusion.owned||typeof fusion.owned!=='object'||Array.isArray(fusion.owned))fusion.owned={};
