 const els=[...new Set(inPossession.map(c=>c.element||'Neutral'))].sort((a,b)=>a==='Neutral'?-1:b==='Neutral'?1:a.localeCompare(b,'de'));
 return `<div class="fusionElementFilter"><strong>Element auswählen</strong><div class="fusionFilters">${[['all','🌈 Alle Elemente'],...els.map(e=>[e,`${fpal(e)[2]} ${e}`])].map(([id,label])=>`<button class="fusionFilter ${fusionElement===id?'selected':''}" data-fact="element:${fesc(id)}">${fesc(label)}</button>`).join('')}</div></div>`;
