function fusionRarity(c){return ({common:'Gewöhnlich',uncommon:'Ungewöhnlich',rare:'Selten',epic:'Episch',legendary:'Legendär'})[c.rarity]||'Gewöhnlich'}
function fusionRollCard(minRarity='common',element=null){
 const levels=['common','uncommon','rare','epic','legendary'];
 const weights=[65,23,9,2.5,.5];
 let pool=DD.CARDS.filter(c=>c.kind==='spell'&&(!element||c.element===element));
 if(!pool.length)return null;
 let r=Math.random()*weights.slice(levels.indexOf(minRarity)).reduce((a,b)=>a+b,0),chosen=minRarity;
 for(let i=levels.indexOf(minRarity);i<levels.length;i++){r-=weights[i];if(r<=0){chosen=levels[i];break}}
 const tier=pool.filter(c=>c.rarity===chosen);
 const fallback=pool.filter(c=>levels.indexOf(c.rarity)>=levels.indexOf(minRarity));
 const choices=tier.length?tier:fallback.length?fallback:pool;
 return choices[Math.floor(Math.random()*choices.length)];
}
function fusionGrantCard(c){if(!c)return;fusion.owned[c.id]=(fusion.owned[c.id]||0)+1;fusionSave()}
const VK_PACKS={
 common:{name:'Gewöhnlicher Booster',cost:180,weights:[70,21,7,1.8,.2],guarantee:'uncommon'},
 rare:{name:'Seltener Booster',cost:420,weights:[30,35,25,9,1],guarantee:'rare'},
 epic:{name:'Epischer Booster',cost:950,weights:[8,22,32,30,8],guarantee:'epic'},
 legendary:{name:'Legendärer Booster',cost:2100,weights:[0,10,25,40,25],guarantee:'legendary'}
};
function vkPackCard(kind,minRarity){
 const levels=['common','uncommon','rare','epic','legendary'];
 const pack=VK_PACKS[kind]||VK_PACKS.common;
 let weights=pack.weights.map((w,i)=>i<levels.indexOf(minRarity)?0:w);
 const pool=DD.CARDS.filter(c=>c.kind==='spell'&&!c.teamAttack&&!c.id.startsWith('mon-'));
 // Pick only tiers with actual available cards.
 weights=weights.map((w,i)=>pool.some(c=>c.rarity===levels[i])?w:0);
 const total=weights.reduce((a,b)=>a+b,0);
 if(!total)return fusionRollCard(minRarity);
 let roll=Math.random()*total,tier=levels[0];
 for(let i=0;i<weights.length;i++){roll-=weights[i];if(roll<0){tier=levels[i];break}}
 const options=pool.filter(c=>c.rarity===tier);
 return options[Math.floor(Math.random()*options.length)];
}
