creatureArt=function(id,shiny=false,mon=null){
 try{return vkCreatureSvg(mon||{id,lv:1,shiny:!!shiny})}catch(err){console.error('Creature SVG:',err);return ''}
};
fusionPortrait=function(m){return m?vkCreatureSvg(m):''};
